import apiClient from './apiClient';

// Helper function to ensure slashes are properly handled
const formatEndpoint = (path) => {
  // Make sure path starts with a slash
  if (!path.startsWith('/')) {
    path = '/' + path;
  }
  return path;
};

export const getAllEntries = async (username, sort = null) => {
  let endpoint = formatEndpoint(`user/${username}/entry/getAll`);
  
  if (sort) {
    endpoint += `?sort=${sort}`;
  }
  
  try {
    console.log('Making request to:', endpoint);
    const response = await apiClient.get(endpoint);
    console.log('GetAllEntries response:', response.data);
    return response.data;
  } catch (error) {
    console.error('Error fetching entries:', error);
    console.error('Error details:', error.response?.data);
    throw error;
  }
};

export const getFilteredEntries = async (username, filters = {}) => {
  const { type, search, sortBy, sortOrder } = filters;
  let queryParams = [];
  
  if (type) queryParams.push(`type=${type}`);
  if (search) queryParams.push(`search=${search}`);
  if (sortBy) queryParams.push(`sort_by=${sortBy}`);
  if (sortOrder) queryParams.push(`sort_order=${sortOrder}`);
  
  const queryString = queryParams.length > 0 ? `?${queryParams.join('&')}` : '';
  const endpoint = formatEndpoint(`user/${username}/entry/getFiltered${queryString}`);
  
  try {
    console.log('Making filtered request to:', endpoint);
    const response = await apiClient.get(endpoint);
    console.log('GetFilteredEntries response:', response.data);
    return response.data;
  } catch (error) {
    console.error('Error fetching filtered entries:', error);
    throw error;
  }
};

export const createEntry = async (username, entryData) => {
  const endpoint = formatEndpoint(`user/${username}/entry/addNew`);
  
  try {
    console.log('Creating entry at:', endpoint);
    console.log('Entry data:', entryData);
    const response = await apiClient.post(endpoint, entryData);
    console.log('CreateEntry response:', response.data);
    return response.data;
  } catch (error) {
    console.error('Error creating entry:', error);
    console.error('Request details:', {
      url: endpoint,
      data: entryData,
      error: error.response?.data
    });
    throw error;
  }
};

export const updateEntry = async (username, entryId, entryData) => {
  const endpoint = formatEndpoint(`user/${username}/entry/${entryId}/edit`);
  
  try {
    console.log('Updating entry at:', endpoint);
    console.log('Update data:', entryData);
    const response = await apiClient.put(endpoint, entryData);
    return response.data;
  } catch (error) {
    console.error('Error updating entry:', error);
    throw error;
  }
};

export const deleteEntry = async (username, entryId) => {
  const endpoint = formatEndpoint(`user/${username}/entry/${entryId}`);
  
  try {
    console.log('Deleting entry at:', endpoint);
    const response = await apiClient.delete(endpoint);
    return response.data;
  } catch (error) {
    console.error('Error deleting entry:', error);
    throw error;
  }
};

export const getSummary = async (username) => {
    // Try with the entry path pattern rather than the user path pattern
    const endpoint = formatEndpoint(`user/${username}/entry/summary`);
    
    try {
      console.log('Fetching summary from:', endpoint);
      const response = await apiClient.get(endpoint);
      console.log('Summary response:', response.data);
      return response.data;
    } catch (error) {
      console.error('Error fetching summary:', error);
      // Return default summary to prevent UI errors
      return {
        total_income: 0,
        total_expense: 0,
        balance: 0
      };
    }
  };
